from hermes_tools import write_file, terminal
content='''def transform(grid):
    # The grid is a regular lattice of 5x5 cells separated by color 8.
    # Connect the two markers of each color with a line through the lattice,
    # filling each crossed cell; crossings are color 6.
    h, w = len(grid), len(grid[0])
    row_seps = [r for r in range(h) if all(v == 8 for v in grid[r])]
    col_seps = [c for c in range(w) if all(grid[r][c] == 8 for r in range(h))]
    rh = [r for r in range(h) if r not in row_seps]
    cw = [c for c in range(w) if c not in col_seps]
    # map each interior pixel to its lattice cell
    cells = {}
    for i, r0 in enumerate(rh):
        for j, c0 in enumerate(cw):
            v = grid[r0][c0]
            if v in (2, 3):
                cells.setdefault(v, []).append((i, j))
    out = [row[:] for row in grid]
    for color, points in cells.items():
        if len(points) < 2:
            continue
        (r1, c1), (r2, c2) = points[:2]
        # Iterate lattice cells and include cells touched by the center-to-center segment.
        dr, dc = r2-r1, c2-c1
        n = max(abs(dr), abs(dc))
        if n == 0:
            path = [points[0]]
        else:
            path = []
            for k in range(n+1):
                rr = round(r1 + dr*k/n)
                cc = round(c1 + dc*k/n)
                if (rr,cc) not in path:
                    path.append((rr,cc))
        for i,j in path:
            # Expand each cell to its full dimensions (not separators).
            rr = rh[i]
            cc = cw[j]
            for r in range(rr, next((x for x in row_seps if x>rr), h)):
                for c in range(cc, next((x for x in col_seps if x>cc), w)):
                    if out[r][c] == 0:
                        out[r][c] = color
                    elif out[r][c] in (2,3) and out[r][c] != color:
                        out[r][c] = 6
    return out
'''
